-- 34 Crater Isle: drops bombs and blows craters in the island. The hole
-- in the pixels and the collider that follows it are the engine's - one
-- `Sprite.carve` on the island's `carvable` - so the crates and barrels
-- standing on carved-away ground simply fall. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/34-crater-isle.scene"
local PROPS = 8
local BLAST = 64          -- crater radius
local PUSH = 190          -- how far a blast throws things
local post_on = nav.post_all_on(SCENE)
local captions = true
local island, fire, dirt, smoke, flash, aim, status
local props = {}
local bombs = {}
local flash_t = 0
local dig_t = 0
local craters = 0

local function refresh()
    if status then Text.set(status, "craters " .. craters) end
end

function init(entity)
    island = Entity.find_by_name("Island")
    fire = Entity.find_by_name("BlastFire")
    dirt = Entity.find_by_name("BlastDirt")
    smoke = Entity.find_by_name("BlastSmoke")
    flash = Entity.find_by_name("Flash")
    aim = Entity.find_by_name("Aim")
    status = Entity.find_by_name("Status")
    for i = 1, PROPS do props[#props + 1] = Entity.find_by_name("Prop" .. i) end
    refresh()
end

local function explode(x, y)
    Sprite.carve(island, x, y, BLAST)
    for _, e in ipairs({ fire, dirt, smoke }) do
        if e then
            Transform.set_position(e, x, y)
        end
    end
    if fire then Particles.emit_burst(fire, 90) end
    if dirt then Particles.emit_burst(dirt, 140) end
    if smoke then Particles.emit_burst(smoke, 26) end
    if flash then
        Transform.set_position(flash, x, y)
        flash_t = 0.25
    end
    -- Throw what is near, away from the blast and up.
    for _, p in ipairs(props) do
        local px, py = Transform.get_position(p)
        local dx, dy = px - x, py - y
        local d = math.sqrt(dx * dx + dy * dy)
        if d < PUSH then
            local k = 1 - d / PUSH
            local nx, ny = dx / math.max(d, 1), dy / math.max(d, 1)
            Physics.set_velocity(p, nx * 520 * k, 260 * k + ny * 340 * k)
            Physics.set_angular_velocity(p, (math.random() - 0.5) * 14 * k)
        end
    end
    craters = craters + 1
    refresh()
end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_captions(captions) end
    if Input.is_key_just_pressed("R") then
        Scene.load(SCENE)
        return
    end
    if island == nil then return end
    local mx, my = Input.get_mouse_world_position()
    if aim then Transform.set_position(aim, mx, 330) end

    if Input.is_mouse_left_just_pressed() then
        local b = Entity.spawn_prefab("CiBomb")
        Transform.set_position(b, mx, 400)
        Physics.set_velocity(b, 0, -120)
        bombs[#bombs + 1] = { e = b, age = 0 }
    end
    if Input.is_mouse_right_pressed() then
        dig_t = dig_t - dt
        if dig_t <= 0 then
            Sprite.carve(island, mx, my, 16)
            dig_t = 0.04
        end
    end

    -- A bomb goes off when it lands on something - or falls into the sea.
    for i = #bombs, 1, -1 do
        local b = bombs[i]
        b.age = b.age + dt
        -- A bomb spawned this frame is not in the snapshot until the next.
        local x, y = Transform.get_position(b.e)
        if x == nil then x, y = 0, 1000 end
        local landed = false
        if b.age > 0.15 and y < 900 then
            -- The drawn position is blended between physics steps and runs
            -- a few units ahead of the body, so start clear of the bomb's
            -- own collider (radius 15) and ignore it if the ray finds it.
            local hit = Physics.raycast(x, y - 24, 0, -1, 6)
            if hit ~= nil and hit.entity_id == b.e then hit = nil end
            landed = hit ~= nil
        end
        if landed or y < -250 or b.age > 8 then
            if y > -250 then explode(x, y) end
            Entity.destroy(b.e)
            table.remove(bombs, i)
        end
    end

    if flash and flash_t > 0 then
        flash_t = math.max(0, flash_t - dt)
        Sprite.set_color(flash, 1.0, 0.75, 0.4, flash_t * 3.2)
    end
end
